-- WS-U · Checklists & principals (Phase 2, slot 03).
--
-- checklist_templates    seeded per program (pre-closing items only; generated from lib/checklists/templates.ts)
-- deal_checklists        a deal's checklist, pinned to the template version it was created from
-- deal_checklist_items   one row per item (per-principal items expand per principal)
-- checklist_item_files   portal uploads to the private vault bucket, per item
-- conditions             lender / Kubera / counsel conditions between term sheet and closing
-- principals             ownership chart, guarantors, REO schedule, HUD-2530 data, credit authorization;
--                        SSN/ITIN, date of birth, PFS and Form 1919 answers are application-encrypted
--                        (lib/privacy/crypto.ts) and the table rejects anything that is not ciphertext
-- screenings             OFAC / sanctions screening results with list version, score, disposition, reviewer
-- deal_holds             holds a deal on a possible or confirmed sanctions match (opened by trigger)
-- hm_underwriting        hard money file: ARV, scope of work, track record, exit plan
-- portal_invites         single-use borrower-portal magic links (token hash only)
--
-- deal_id: `deals` is created by WS-I (slot 01). When it exists, the block at the end
-- adds the foreign keys; otherwise the integrator's follow-up migration does.
-- RLS is enabled on every table with no policies: only the service role reads or writes.
-- Kubera is the broker: nothing here records funds or construction draws.

-- Templates ------------------------------------------------------------------------------
create table public.checklist_templates (
  id uuid primary key default gen_random_uuid(),
  created_at timestamptz not null default now(),
  program text not null check (program in (
    'HUD_232_223F', 'HUD_232_NEW_CONSTRUCTION', 'HUD_MULTIFAMILY_223F', 'HUD_221D4', 'SBA_7A', 'SBA_504',
    'HOTEL_CMBS', 'PIP_BRIDGE', 'AGENCY_MULTIFAMILY', 'BRIDGE', 'HARD_MONEY', 'CONSTRUCTION'
  )),
  version text not null check (version ~ '^\d{4}\.\d{1,2}\.\d{1,3}$'),
  title text not null check (length(title) between 3 and 200),
  items jsonb not null check (jsonb_typeof(items) = 'array' and jsonb_array_length(items) > 0),
  retired_at timestamptz,
  unique (program, version)
);

-- Principals ----------------------------------------------------------------------------------
create table public.principals (
  id uuid primary key,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  version integer not null default 1 check (version > 0),
  deal_id uuid not null,
  lead_id uuid references public.leads (id) on delete set null,
  parent_id uuid references public.principals (id) on delete restrict,
  kind text not null check (kind in ('individual', 'entity')),
  legal_name text not null check (length(legal_name) between 2 and 200),
  roles text[] not null check (
    cardinality(roles) between 1 and 8
    and roles <@ array['borrower_entity', 'managing_member', 'general_partner', 'member', 'limited_partner', 'shareholder',
                       'officer', 'director', 'trustee', 'guarantor', 'key_principal', 'operator', 'management_agent']::text[]
  ),
  title text check (title is null or length(title) <= 120),
  ownership_pct numeric(7, 4) check (ownership_pct is null or ownership_pct between 0 and 100),
  is_guarantor boolean not null default false,
  email text check (email is null or (email = lower(email) and email ~ '^[^@\s]+@[^@\s]+$')),
  phone text check (phone is null or length(phone) <= 40),
  home_address text check (home_address is null or length(home_address) <= 300),
  formation_state text check (formation_state is null or formation_state ~ '^[A-Z]{2}$'),
  citizenship text check (citizenship in ('us_citizen', 'lawful_permanent_resident', 'other')),
  -- Restricted (CCPA sensitive PI): AES-256-GCM envelopes only, never plaintext.
  ssn text check (ssn is null or ssn ~ '^pii1\.\d{1,5}\.[A-Za-z0-9_-]{16}\.[A-Za-z0-9_-]*\.[A-Za-z0-9_-]{22}$'),
  dob text check (dob is null or dob ~ '^pii1\.\d{1,5}\.[A-Za-z0-9_-]{16}\.[A-Za-z0-9_-]*\.[A-Za-z0-9_-]{22}$'),
  pfs text check (pfs is null or pfs ~ '^pii1\.\d{1,5}\.[A-Za-z0-9_-]{16}\.[A-Za-z0-9_-]*\.[A-Za-z0-9_-]{22}$'),
  form_1919 text check (form_1919 is null or form_1919 ~ '^pii1\.\d{1,5}\.[A-Za-z0-9_-]{16}\.[A-Za-z0-9_-]*\.[A-Za-z0-9_-]{22}$'),
  -- Keyed blind index of the tax id (HMAC), for duplicate detection without decrypting.
  tax_id_index text check (tax_id_index is null or tax_id_index ~ '^bi1\.\d{1,5}\.[0-9a-f]{64}$'),
  pfs_as_of date,
  has_ssn boolean generated always as (ssn is not null) stored,
  has_dob boolean generated always as (dob is not null) stored,
  has_pfs boolean generated always as (pfs is not null) stored,
  has_form_1919 boolean generated always as (form_1919 is not null) stored,
  -- Confidential exhibits.
  reo_schedule jsonb check (reo_schedule is null or jsonb_typeof(reo_schedule) = 'array'),
  hud_2530 jsonb check (hud_2530 is null or jsonb_typeof(hud_2530) = 'object'),
  credit_authorization jsonb check (credit_authorization is null or (
    jsonb_typeof(credit_authorization) = 'object'
    and credit_authorization ? 'textVersion' and credit_authorization ? 'textSha256'
    and credit_authorization ? 'consentedAt' and credit_authorization ? 'signatureName'
  )),
  constraint principals_not_own_parent check (parent_id is null or parent_id <> id),
  constraint principals_borrower_is_root check (
    case when 'borrower_entity' = any (roles) then parent_id is null and kind = 'entity' and ownership_pct is null
         else parent_id is not null end
  ),
  constraint principals_individual_fields check (
    kind = 'individual' or (ssn is null and dob is null and pfs is null and form_1919 is null and home_address is null and citizenship is null)
  ),
  constraint principals_pfs_dated check (pfs is null or pfs_as_of is not null),
  constraint principals_ssn_indexed check ((ssn is null) = (tax_id_index is null))
);
create unique index principals_one_borrower_per_deal on public.principals (deal_id) where 'borrower_entity' = any (roles);
create index principals_deal_idx on public.principals (deal_id, created_at);
create index principals_parent_idx on public.principals (parent_id) where parent_id is not null;
create index principals_tax_id_index_idx on public.principals (tax_id_index) where tax_id_index is not null;
create index principals_email_idx on public.principals (email) where email is not null;

create or replace function public.principals_parent_same_deal()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.parent_id is not null and not exists (
    select 1 from public.principals p where p.id = new.parent_id and p.deal_id = new.deal_id and p.kind = 'entity'
  ) then
    raise exception 'Principal % must sit under an entity on the same deal', new.id using errcode = 'check_violation';
  end if;
  return new;
end;
$$;
create trigger principals_parent_same_deal before insert or update of parent_id, deal_id on public.principals
  for each row execute function public.principals_parent_same_deal();
create trigger principals_touch before update on public.principals
  for each row execute function public.touch_updated_at();

-- Deal checklists ------------------------------------------------------------------------------
create table public.deal_checklists (
  id uuid primary key default gen_random_uuid(),
  created_at timestamptz not null default now(),
  deal_id uuid not null,
  lead_id uuid references public.leads (id) on delete set null,
  program text not null,
  template_version text not null,
  title text not null check (length(title) between 3 and 200),
  created_by text not null check (length(created_by) between 1 and 200),
  closed_at timestamptz,
  unique (deal_id, program),
  foreign key (program, template_version) references public.checklist_templates (program, version) on delete restrict
);
create index deal_checklists_created_idx on public.deal_checklists (created_at desc);

create table public.deal_checklist_items (
  id uuid primary key default gen_random_uuid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  version integer not null default 1 check (version > 0),
  checklist_id uuid not null references public.deal_checklists (id) on delete cascade,
  deal_id uuid not null,
  item_key text not null check (item_key ~ '^[a-z0-9_]+(:[0-9a-f-]{36})?$'),
  template_key text not null check (template_key ~ '^[a-z0-9_]+$'),
  principal_id uuid references public.principals (id) on delete set null,
  title text not null check (length(title) between 2 and 300),
  description text not null check (length(description) <= 2000),
  category text not null check (category in ('entity', 'principal', 'financial', 'property', 'third_party', 'construction', 'title_insurance', 'program')),
  responsible text not null check (responsible in ('borrower', 'kubera', 'lender', 'vendor', 'title_escrow')),
  stage text not null check (stage in ('application', 'underwriting', 'pre_closing')),
  required boolean not null,
  upload boolean not null,
  doc_kind text check (doc_kind in ('T12', 'RENT_ROLL', 'CENSUS', 'STR_REPORT', 'FRANCHISE_AGREEMENT', 'PIP_BUDGET', 'PFS', 'TAX_RETURN', 'APPRAISAL', 'OTHER')),
  recency_days integer check (recency_days is null or recency_days between 1 and 730),
  lookup text check (lookup in ('cslb_license')),
  status text not null default 'requested' check (status in ('requested', 'submitted', 'under_review', 'accepted', 'rejected', 'waived', 'not_applicable')),
  document_date date,
  due_date date,
  submitted_at timestamptz,
  reviewed_at timestamptz,
  reviewed_by text check (reviewed_by is null or length(reviewed_by) <= 200),
  review_note text check (review_note is null or length(review_note) <= 2000),
  waived_reason text check (waived_reason is null or length(waived_reason) <= 2000),
  verification jsonb check (verification is null or jsonb_typeof(verification) = 'object'),
  sort_order integer not null default 0,
  unique (checklist_id, item_key),
  constraint deal_checklist_items_waiver_reason check (status not in ('waived', 'not_applicable') or waived_reason is not null),
  constraint deal_checklist_items_rejection_note check (status <> 'rejected' or review_note is not null),
  constraint deal_checklist_items_accepted_reviewer check (status <> 'accepted' or reviewed_by is not null),
  constraint deal_checklist_items_principal_key check ((principal_id is null) = (item_key !~ ':') or status = 'not_applicable')
);
create index deal_checklist_items_deal_idx on public.deal_checklist_items (deal_id, sort_order);
create index deal_checklist_items_open_idx on public.deal_checklist_items (deal_id) where status in ('requested', 'rejected');
create trigger deal_checklist_items_touch before update on public.deal_checklist_items
  for each row execute function public.touch_updated_at();

create table public.checklist_item_files (
  id uuid primary key,
  created_at timestamptz not null default now(),
  item_id uuid not null references public.deal_checklist_items (id) on delete restrict,
  deal_id uuid not null,
  storage_path text not null unique check (storage_path ~ '^deals/[0-9a-f-]{36}/checklist/[0-9a-f-]{36}/[0-9a-f-]{36}-[A-Za-z0-9_.-]+$'),
  file_name text not null check (length(file_name) between 1 and 200),
  content_type text not null check (content_type in (
    'application/pdf', 'text/csv', 'application/vnd.ms-excel',
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', 'image/png', 'image/jpeg'
  )),
  size_bytes bigint not null check (size_bytes between 1 and 52428800),
  status text not null check (status in ('pending_upload', 'uploaded', 'rejected')),
  uploaded_by text not null check (length(uploaded_by) between 3 and 200),
  uploaded_at timestamptz,
  reject_reason text check (reject_reason is null or length(reject_reason) <= 500),
  constraint checklist_item_files_uploaded_time check (status <> 'uploaded' or uploaded_at is not null),
  constraint checklist_item_files_rejected_reason check (status <> 'rejected' or reject_reason is not null)
);
create index checklist_item_files_item_idx on public.checklist_item_files (item_id);
create index checklist_item_files_deal_idx on public.checklist_item_files (deal_id, created_at);

-- Conditions --------------------------------------------------------------------------------------
create table public.conditions (
  id uuid primary key default gen_random_uuid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  version integer not null default 1 check (version > 0),
  deal_id uuid not null,
  source text not null check (source in ('lender', 'kubera', 'counsel', 'title', 'hud', 'sba', 'cdc')),
  lender_name text check (lender_name is null or length(lender_name) between 2 and 200),
  timing text not null check (timing in ('prior_to_approval', 'prior_to_docs', 'prior_to_closing', 'at_closing', 'post_closing')),
  description text not null check (length(description) between 5 and 2000),
  status text not null default 'open' check (status in ('open', 'submitted', 'cleared', 'waived', 'rejected')),
  responsible text not null check (responsible in ('borrower', 'kubera', 'lender', 'vendor', 'title_escrow')),
  due_date date,
  checklist_item_id uuid references public.deal_checklist_items (id) on delete set null,
  notes text check (notes is null or length(notes) <= 2000),
  cleared_by text,
  cleared_at timestamptz,
  waiver_reason text check (waiver_reason is null or length(waiver_reason) <= 2000),
  waiver_evidence text check (waiver_evidence is null or length(waiver_evidence) <= 500),
  created_by text not null,
  constraint conditions_lender_named check (source <> 'lender' or lender_name is not null),
  constraint conditions_done_has_who check (status not in ('cleared', 'waived') or (cleared_by is not null and cleared_at is not null)),
  constraint conditions_waiver_reason check (status <> 'waived' or waiver_reason is not null),
  -- Only Kubera can waive its own condition without the imposing party's written waiver.
  constraint conditions_waiver_evidence check (status <> 'waived' or source = 'kubera' or waiver_evidence is not null)
);
create index conditions_deal_idx on public.conditions (deal_id, created_at);
create index conditions_open_idx on public.conditions (deal_id) where status in ('open', 'submitted', 'rejected');
create trigger conditions_touch before update on public.conditions
  for each row execute function public.touch_updated_at();

-- Screenings -------------------------------------------------------------------------------------------
create table public.screenings (
  id uuid primary key default gen_random_uuid(),
  created_at timestamptz not null default now(),
  deal_id uuid not null,
  principal_id uuid references public.principals (id) on delete set null,
  subject_kind text not null check (subject_kind in ('individual', 'entity')),
  subject_name text not null check (length(subject_name) between 2 and 200),
  purpose text not null check (purpose in ('initial', 'rescreen_pre_closing', 'periodic', 'manual')),
  provider text not null check (length(provider) between 1 and 60),
  list_version text check (list_version is null or length(list_version) between 1 and 200),
  lists_checked text[] not null default '{}',
  result text not null check (result in ('clear', 'potential_match', 'error')),
  match_score numeric(5, 4) check (match_score is null or match_score between 0 and 1),
  matches jsonb not null default '[]' check (jsonb_typeof(matches) = 'array'),
  error text check (error is null or length(error) <= 500),
  disposition text not null check (disposition in ('not_required', 'pending_review', 'false_positive', 'confirmed_match', 'escalated')),
  reviewer text check (reviewer is null or length(reviewer) <= 200),
  reviewed_at timestamptz,
  review_note text check (review_note is null or length(review_note) between 10 and 2000),
  requested_by text not null check (length(requested_by) between 1 and 200),
  screened_at timestamptz not null,
  constraint screenings_error_message check (result <> 'error' or error is not null),
  constraint screenings_list_version check (result = 'error' or list_version is not null),
  constraint screenings_disposition_fits check (
    (result = 'potential_match' and disposition in ('pending_review', 'false_positive', 'confirmed_match', 'escalated'))
    or (result <> 'potential_match' and disposition = 'not_required')
  ),
  constraint screenings_review_complete check (
    disposition not in ('false_positive', 'confirmed_match', 'escalated') or (reviewer is not null and reviewed_at is not null and review_note is not null)
  )
);
create index screenings_deal_idx on public.screenings (deal_id, screened_at);
create index screenings_principal_idx on public.screenings (principal_id, screened_at desc) where principal_id is not null;
create index screenings_review_idx on public.screenings (created_at) where disposition in ('pending_review', 'escalated');

-- Results are evidence: only the review fields change, along the allowed path, and rows are never deleted.
create or replace function public.screenings_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'DELETE' then
    raise exception 'Screenings are retained records and cannot be deleted' using errcode = 'insufficient_privilege';
  end if;
  if (new.id, new.created_at, new.deal_id, new.subject_kind, new.subject_name, new.purpose, new.provider, new.list_version,
      new.lists_checked, new.result, new.match_score, new.matches, new.error, new.requested_by, new.screened_at)
     is distinct from
     (old.id, old.created_at, old.deal_id, old.subject_kind, old.subject_name, old.purpose, old.provider, old.list_version,
      old.lists_checked, old.result, old.match_score, old.matches, old.error, old.requested_by, old.screened_at) then
    raise exception 'Screening results are immutable' using errcode = 'insufficient_privilege';
  end if;
  if new.principal_id is distinct from old.principal_id and new.principal_id is not null then
    raise exception 'A screening cannot move to another principal' using errcode = 'insufficient_privilege';
  end if;
  if new.disposition is distinct from old.disposition and not (
    (old.disposition = 'pending_review' and new.disposition in ('false_positive', 'confirmed_match', 'escalated'))
    or (old.disposition = 'escalated' and new.disposition in ('false_positive', 'confirmed_match'))
  ) then
    raise exception 'Screening disposition cannot change from % to %', old.disposition, new.disposition using errcode = 'check_violation';
  end if;
  return new;
end;
$$;
create trigger screenings_guard before update or delete on public.screenings
  for each row execute function public.screenings_guard();

-- Deal holds ----------------------------------------------------------------------------------------------
create table public.deal_holds (
  id uuid primary key default gen_random_uuid(),
  created_at timestamptz not null default now(),
  deal_id uuid not null,
  reason text not null check (reason in ('sanctions_potential_match', 'sanctions_confirmed_match', 'counsel_review')),
  source_kind text not null check (source_kind in ('screening')),
  source_id uuid not null,
  detail text not null check (length(detail) between 5 and 1000),
  created_by text not null,
  released_at timestamptz,
  released_by text,
  release_note text check (release_note is null or length(release_note) <= 2000),
  constraint deal_holds_release_complete check (released_at is null or (released_by is not null and release_note is not null))
);
create unique index deal_holds_one_open_per_source on public.deal_holds (source_kind, source_id, reason) where released_at is null;
create index deal_holds_active_idx on public.deal_holds (deal_id) where released_at is null;

create or replace function public.deal_holds_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'DELETE' then
    raise exception 'Deal holds are retained records and cannot be deleted' using errcode = 'insufficient_privilege';
  end if;
  if old.released_at is not null then
    raise exception 'Hold % was already released', old.id using errcode = 'check_violation';
  end if;
  if (new.id, new.created_at, new.deal_id, new.reason, new.source_kind, new.source_id, new.detail, new.created_by)
     is distinct from (old.id, old.created_at, old.deal_id, old.reason, old.source_kind, old.source_id, old.detail, old.created_by) then
    raise exception 'Only the release fields of a hold can change' using errcode = 'insufficient_privilege';
  end if;
  -- A confirmed match is released only through counsel, never by clearing the screening.
  if old.reason = 'sanctions_confirmed_match' and coalesce(current_setting('kubera.counsel_release', true), '') <> 'on' then
    raise exception 'A confirmed sanctions match hold can only be released by counsel' using errcode = 'insufficient_privilege';
  end if;
  return new;
end;
$$;
create trigger deal_holds_guard before update or delete on public.deal_holds
  for each row execute function public.deal_holds_guard();

-- A possible match holds the deal the moment it is recorded, whoever writes the row;
-- clearing it as a false positive releases that hold; confirming it adds a confirmed-match hold.
create or replace function public.screenings_hold_deal()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' and new.result = 'potential_match' then
    insert into public.deal_holds (deal_id, reason, source_kind, source_id, detail, created_by)
    values (new.deal_id, 'sanctions_potential_match', 'screening', new.id,
            format('Possible sanctions match for %s (score %s, %s).', new.subject_name, coalesce(new.match_score::text, 'n/a'), coalesce(new.list_version, 'unknown list')),
            new.requested_by)
    on conflict (source_kind, source_id, reason) where released_at is null do nothing;
  elsif tg_op = 'UPDATE' and new.disposition is distinct from old.disposition then
    if new.disposition = 'false_positive' then
      update public.deal_holds
         set released_at = now(), released_by = new.reviewer, release_note = new.review_note
       where source_kind = 'screening' and source_id = new.id and reason = 'sanctions_potential_match' and released_at is null;
    elsif new.disposition = 'confirmed_match' then
      insert into public.deal_holds (deal_id, reason, source_kind, source_id, detail, created_by)
      values (new.deal_id, 'sanctions_confirmed_match', 'screening', new.id,
              format('Confirmed sanctions match for %s. Do not proceed; counsel review required.', new.subject_name), new.reviewer)
      on conflict (source_kind, source_id, reason) where released_at is null do nothing;
    end if;
  end if;
  return null;
end;
$$;
create trigger screenings_hold_deal after insert or update of disposition on public.screenings
  for each row execute function public.screenings_hold_deal();

-- Current hold state per deal for pipeline gates (security_invoker so the caller's RLS applies).
create view public.deal_hold_status
with (security_invoker = true)
as
select h.deal_id,
       count(*) as active_holds,
       array_agg(distinct h.reason order by h.reason) as reasons,
       bool_or(h.reason = 'sanctions_confirmed_match') as counsel_review,
       min(h.created_at) as held_since
from public.deal_holds h
where h.released_at is null
group by h.deal_id;

-- Hard money underwriting ------------------------------------------------------------------------------
create table public.hm_underwriting (
  id uuid primary key default gen_random_uuid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  version integer not null default 1 check (version > 0),
  deal_id uuid not null unique,
  strategy text not null check (strategy in ('FIX_AND_FLIP', 'BRIDGE')),
  purpose text not null check (purpose in ('PURCHASE', 'REFINANCE')),
  purchase_price numeric(14, 2) not null check (purchase_price >= 0),
  as_is_value numeric(14, 2) not null check (as_is_value >= 0),
  arv numeric(14, 2) not null check (arv >= 0),
  arv_source text not null check (arv_source in ('appraisal', 'bpo', 'comparable_sales', 'sponsor_estimate')),
  requested_loan_amount numeric(14, 2) not null check (requested_loan_amount >= 0),
  contingency_pct numeric(5, 2) not null check (contingency_pct between 0 and 50),
  scope_of_work jsonb not null default '[]' check (jsonb_typeof(scope_of_work) = 'array'),
  track_record jsonb not null default '[]' check (jsonb_typeof(track_record) = 'array'),
  exit_plan jsonb not null check (jsonb_typeof(exit_plan) = 'object' and exit_plan ? 'type'),
  notes text check (notes is null or length(notes) <= 4000),
  metrics jsonb not null check (jsonb_typeof(metrics) = 'object'),
  prepared_by text not null
);
create trigger hm_underwriting_touch before update on public.hm_underwriting
  for each row execute function public.touch_updated_at();

-- Borrower portal magic links ----------------------------------------------------------------------------
create table public.portal_invites (
  id uuid primary key default gen_random_uuid(),
  created_at timestamptz not null default now(),
  deal_id uuid not null,
  principal_id uuid references public.principals (id) on delete cascade,
  email text not null check (email = lower(email) and email ~ '^[^@\s]+@[^@\s]+$'),
  token_hash text not null unique check (token_hash ~ '^[0-9a-f]{64}$'),
  expires_at timestamptz not null,
  consumed_at timestamptz,
  revoked_at timestamptz,
  session_expires_at timestamptz,
  created_by text not null,
  constraint portal_invites_expiry check (expires_at > created_at and expires_at <= created_at + interval '7 days'),
  constraint portal_invites_session check ((consumed_at is null) = (session_expires_at is null))
);
create index portal_invites_deal_idx on public.portal_invites (deal_id, created_at desc);

-- RLS: service role only -------------------------------------------------------------------------------------
alter table public.checklist_templates enable row level security;
alter table public.principals enable row level security;
alter table public.deal_checklists enable row level security;
alter table public.deal_checklist_items enable row level security;
alter table public.checklist_item_files enable row level security;
alter table public.conditions enable row level security;
alter table public.screenings enable row level security;
alter table public.deal_holds enable row level security;
alter table public.hm_underwriting enable row level security;
alter table public.portal_invites enable row level security;

revoke all on public.checklist_templates, public.principals, public.deal_checklists, public.deal_checklist_items,
  public.checklist_item_files, public.conditions, public.screenings, public.deal_holds, public.hm_underwriting,
  public.portal_invites, public.deal_hold_status from anon, authenticated;
revoke execute on function public.principals_parent_same_deal(), public.screenings_guard(), public.deal_holds_guard(),
  public.screenings_hold_deal() from public, anon, authenticated;

-- Deal foreign keys when WS-I's deals table is present ------------------------------------------------------------
do $$
declare
  t text;
begin
  if exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = 'deals' and column_name = 'id' and data_type = 'uuid'
  ) then
    foreach t in array array['principals', 'deal_checklists', 'deal_checklist_items', 'checklist_item_files', 'conditions',
                             'screenings', 'deal_holds', 'hm_underwriting', 'portal_invites'] loop
      execute format('alter table public.%I add constraint %I foreign key (deal_id) references public.deals (id) on delete restrict', t, t || '_deal_fk');
    end loop;
  end if;
end;
$$;

